/**
 * The Homebrew formula for a published release, from its checksums.txt.
 * Nothing is rebuilt: each platform installs the release's
 * tracetoon-skill-<target>.zip (the skill with that platform's binary in bin/).
 *
 *   bun .github/scripts/homebrew-formula.ts <checksums.txt> <tag> > tracetoon.rb
 *
 * The formula is meant for a tap at Tracetoon/homebrew-tap
 * (`brew install tracetoon/tap/tracetoon`); docs/release-channels.md says how
 * it gets there. Formula syntax follows https://docs.brew.sh/Formula-Cookbook:
 * `on_macos`/`on_linux` with nested `on_arm`/`on_intel` blocks for per-platform
 * `url`/`sha256`, `write_env_script` for environment variables, and a `test do`
 * block that runs the program (https://docs.brew.sh/Formula-Cookbook#add-a-test-to-the-formula).
 */
import { readFileSync } from 'node:fs';
import { readChecksums, releaseVersion } from './release-assets.ts';

export const RELEASES = 'https://github.com/Tracetoon/tracetoon/releases/download';

const PLATFORMS = [
  { block: 'on_macos', cpu: 'on_arm', target: 'darwin-arm64' },
  { block: 'on_macos', cpu: 'on_intel', target: 'darwin-x64' },
  { block: 'on_linux', cpu: 'on_arm', target: 'linux-arm64' },
  { block: 'on_linux', cpu: 'on_intel', target: 'linux-x64' },
] as const;

/** The release asset each Homebrew platform installs, with its URL and SHA-256. */
export function homebrewAssets(checksums: string, tag: string) {
  releaseVersion(tag);
  const sums = readChecksums(checksums);
  return PLATFORMS.map((p) => {
    const name = `tracetoon-skill-${p.target}.zip`;
    const sha256 = sums.get(name);
    if (!sha256) throw Error(`checksums.txt has no ${name}.`);
    return { ...p, name, url: `${RELEASES}/${tag}/${name}`, sha256 };
  });
}

export function homebrewFormula(checksums: string, tag: string): string {
  const version = releaseVersion(tag);
  const assets = homebrewAssets(checksums, tag);
  const blocks = ['on_macos', 'on_linux'].map((block) =>
    [
      `  ${block} do`,
      ...assets
        .filter((a) => a.block === block)
        .flatMap((a) => [
          `    ${a.cpu} do`,
          `      url "${a.url}"`,
          `      sha256 "${a.sha256}"`,
          `    end`,
        ]),
      `  end`,
    ].join('\n'),
  );
  return `# Generated by .github/scripts/homebrew-formula.ts from the ${tag} release checksums. Do not edit.
class Tracetoon < Formula
  desc "Write pull request descriptions from coding agents' session logs"
  homepage "https://tracetoon.ai"
  version "${version}"
  license "Apache-2.0"

${blocks.join('\n\n')}

  def install
    # The archive holds the skill folder (tracetoon/) with this platform's binary in bin/.
    skill = File.exist?("SKILL.md") ? Pathname.pwd : Pathname.pwd/"tracetoon"
    libexec.install skill.children
    binary = Dir["#{libexec}/bin/tracetoon-*"].reject { |f| f.end_with?(".build.json") }.first
    odie "the release archive has no binary" if binary.nil?
    chmod 0755, binary
    # The binary finds its fonts in ../assets; TRACETOON_SKILL_DIR lets \`tracetoon setup\` install the skill.
    (bin/"tracetoon").write_env_script binary, TRACETOON_SKILL_DIR: libexec
  end

  def caveats
    <<~EOS
      Add the skill and PR hook to your coding agents:
        tracetoon setup
      Run it again after \`brew upgrade tracetoon\` so the hook follows the new version.
    EOS
  end

  test do
    assert_match "\\"version\\": \\"#{version}\\"", shell_output("#{bin}/tracetoon build-info --json")
  end
end
`;
}

if (import.meta.main) {
  const [checksums, tag] = process.argv.slice(2);
  if (!checksums || !tag) throw Error('Use: homebrew-formula.ts <checksums.txt> <tag>');
  process.stdout.write(homebrewFormula(readFileSync(checksums, 'utf8'), tag));
}
